-- ============================================================
-- Social Media Platform — PostgreSQL Database Schema
-- ============================================================
-- Covers: users, posts, comments, likes, follows, messages,
--         notifications
-- ============================================================

BEGIN;

-- -----------------------------------------------------------
-- 1. Users
-- -----------------------------------------------------------
CREATE TYPE account_status AS ENUM ('active', 'suspended', 'deactivated', 'banned');

CREATE TABLE users (
    id              BIGSERIAL       PRIMARY KEY,
    username        VARCHAR(30)     NOT NULL UNIQUE,
    email           VARCHAR(255)    NOT NULL UNIQUE,
    display_name    VARCHAR(100)    NOT NULL,
    password_hash   TEXT            NOT NULL,
    bio             TEXT            DEFAULT '',
    avatar_url      VARCHAR(500),
    status          account_status  NOT NULL DEFAULT 'active',
    is_verified     BOOLEAN         NOT NULL DEFAULT FALSE,
    last_login_at   TIMESTAMPTZ,
    created_at      TIMESTAMPTZ     NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ     NOT NULL DEFAULT now()
);

CREATE INDEX idx_users_username      ON users (username);
CREATE INDEX idx_users_email         ON users (email);
CREATE INDEX idx_users_status        ON users (status);

-- -----------------------------------------------------------
-- 2. Posts
-- -----------------------------------------------------------
CREATE TABLE posts (
    id              BIGSERIAL       PRIMARY KEY,
    author_id       BIGINT          NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    content         TEXT            NOT NULL,
    media_urls      TEXT[]          DEFAULT '{}',       -- array of media attachment URLs
    visibility      VARCHAR(10)     NOT NULL DEFAULT 'public'   -- public | followers | private
                    CHECK (visibility IN ('public','followers','private')),
    like_count      INT             NOT NULL DEFAULT 0, -- denormalised counter
    comment_count   INT             NOT NULL DEFAULT 0,
    created_at      TIMESTAMPTZ     NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ     NOT NULL DEFAULT now()
);

CREATE INDEX idx_posts_author       ON posts (author_id);
CREATE INDEX idx_posts_created      ON posts (created_at DESC);
CREATE INDEX idx_posts_visibility   ON posts (visibility);

-- -----------------------------------------------------------
-- 3. Comments
-- -----------------------------------------------------------
CREATE TABLE comments (
    id              BIGSERIAL       PRIMARY KEY,
    post_id         BIGINT          NOT NULL REFERENCES posts(id) ON DELETE CASCADE,
    author_id       BIGINT          NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    parent_id       BIGINT          REFERENCES comments(id) ON DELETE CASCADE,  -- threaded replies
    content         TEXT            NOT NULL,
    like_count      INT             NOT NULL DEFAULT 0,
    created_at      TIMESTAMPTZ     NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ     NOT NULL DEFAULT now()
);

CREATE INDEX idx_comments_post       ON comments (post_id, created_at);
CREATE INDEX idx_comments_parent     ON comments (parent_id);
CREATE INDEX idx_comments_author     ON comments (author_id);

-- -----------------------------------------------------------
-- 4. Likes  (polymorphic — posts & comments)
-- -----------------------------------------------------------
CREATE TABLE likes (
    id              BIGSERIAL       PRIMARY KEY,
    user_id         BIGINT          NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    target_type     VARCHAR(10)     NOT NULL CHECK (target_type IN ('post','comment')),
    target_id       BIGINT          NOT NULL,
    created_at      TIMESTAMPTZ     NOT NULL DEFAULT now(),

    UNIQUE (user_id, target_type, target_id)
);

-- Partial indexes keep per-type lookups fast
CREATE INDEX idx_likes_post         ON likes (target_id) WHERE target_type = 'post';
CREATE INDEX idx_likes_comment      ON likes (target_id) WHERE target_type = 'comment';
CREATE INDEX idx_likes_user         ON likes (user_id);

-- -----------------------------------------------------------
-- 5. Follows  (user → user)
-- -----------------------------------------------------------
CREATE TABLE follows (
    follower_id     BIGINT          NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    followee_id     BIGINT          NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    created_at      TIMESTAMPTZ     NOT NULL DEFAULT now(),

    PRIMARY KEY (follower_id, followee_id),
    CHECK (follower_id <> followee_id)
);

CREATE INDEX idx_follows_follower   ON follows (follower_id);
CREATE INDEX idx_follows_followee   ON follows (followee_id);

-- -----------------------------------------------------------
-- 6. Direct Messages
-- -----------------------------------------------------------
CREATE TABLE conversations (
    id              BIGSERIAL       PRIMARY KEY,
    created_at      TIMESTAMPTZ     NOT NULL DEFAULT now()
);

-- Many-to-many: a conversation can have exactly 2 participants (DM)
CREATE TABLE conversation_participants (
    conversation_id BIGINT          NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
    user_id         BIGINT          NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    last_read_at    TIMESTAMPTZ     NOT NULL DEFAULT now(),

    PRIMARY KEY (conversation_id, user_id)
);

CREATE TABLE messages (
    id              BIGSERIAL       PRIMARY KEY,
    conversation_id BIGINT          NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
    sender_id       BIGINT          NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    content         TEXT            NOT NULL,
    media_url       VARCHAR(500),
    is_read         BOOLEAN         NOT NULL DEFAULT FALSE,
    created_at      TIMESTAMPTZ     NOT NULL DEFAULT now()
);

CREATE INDEX idx_messages_conversation ON messages (conversation_id, created_at);
CREATE INDEX idx_messages_sender       ON messages (sender_id);

-- -----------------------------------------------------------
-- 7. Notifications
-- -----------------------------------------------------------
CREATE TYPE notification_type AS ENUM (
    'like', 'comment', 'follow', 'mention',
    'message', 'repost', 'follow_request'
);

CREATE TABLE notifications (
    id              BIGSERIAL       PRIMARY KEY,
    recipient_id    BIGINT          NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    actor_id        BIGINT          REFERENCES users(id) ON DELETE SET NULL,
    type            notification_type NOT NULL,
    -- Polymorphic reference — target can be a post, comment, or follow
    target_type     VARCHAR(10),
    target_id       BIGINT,
    message         TEXT            NOT NULL DEFAULT '',    -- pre-rendered display text
    is_read         BOOLEAN         NOT NULL DEFAULT FALSE,
    created_at      TIMESTAMPTZ     NOT NULL DEFAULT now()
);

CREATE INDEX idx_notifications_recipient ON notifications (recipient_id, is_read, created_at DESC);
CREATE INDEX idx_notifications_created    ON notifications (created_at DESC);

-- -----------------------------------------------------------
-- Helper: updated_at trigger (all timestamped tables)
-- -----------------------------------------------------------
CREATE OR REPLACE FUNCTION trg_set_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_users_updated     BEFORE UPDATE ON users      FOR EACH ROW EXECUTE FUNCTION trg_set_updated_at();
CREATE TRIGGER trg_posts_updated     BEFORE UPDATE ON posts      FOR EACH ROW EXECUTE FUNCTION trg_set_updated_at();
CREATE TRIGGER trg_comments_updated  BEFORE UPDATE ON comments   FOR EACH ROW EXECUTE FUNCTION trg_set_updated_at();

COMMIT;
